struct jsonImportInboundsResponseStruct* jsonImportInboundsResponse(const char* json) {
    DBG(LOG_INFO, "Function called");

    struct jsonListInboundStruct* listInStruct = jsonListInbound(json);
    if (!listInStruct) {
        applicationLog(LOG_ERROR, __PRETTY_FUNCTION__, "Failed to parse the list of inbounds, returning...");

        return NULL;

    }

    struct jsonImportInboundsResponseStruct* importInboundsRStruct = (struct jsonImportInboundsResponseStruct*)malloc(sizeof(struct jsonImportInboundsResponseStruct));
    if (!importInboundsRStruct) {
        applicationLog(LOG_ERROR, __PRETTY_FUNCTION__, "importInboundsRStruct is a null pointer, failed to allocate space");

        jsonListInboundStructDelete(listInStruct);

        return NULL;

    }

    importInboundsRStruct->success = listInStruct->success;
    importInboundsRStruct->msg = listInStruct->msg;
    importInboundsRStruct->jsonListInboundObjectStructSize = listInStruct->jsonListInboundObjectStructSize;
    importInboundsRStruct->listInObjStruct = listInStruct->listInObjStruct;

    free(listInStruct);

    return importInboundsRStruct;

}
